'use strict';

/**
 * prepare-runtime.js
 *
 * Assembles a self-contained runtime folder (`resources/runtime/`) from a
 * clone of the upstream `lfnovo/open-notebook` repository. The runtime bundles
 * everything the desktop app needs to run offline:
 *
 *   runtime/
 *     python/        standalone CPython 3.12 with all backend dependencies
 *     backend/       the Open Notebook Python code (api, open_notebook, ...)
 *     frontend/      the built Next.js standalone server + static assets
 *     surreal/       the SurrealDB Windows binary
 *     node/          a portable Node.js runtime for the frontend server
 *     tiktoken-cache pre-downloaded tiktoken encoding (offline support)
 *
 * Usage:
 *   node scripts/prepare-runtime.js [--repo <path>] [--step <name>]
 *
 * Steps: frontend | python | surreal | node | tiktoken | backend | all
 */

const { spawnSync } = require('child_process');
const fs = require('fs');
const os = require('os');
const path = require('path');
const crypto = require('crypto');
const https = require('https');
const http = require('http');

const PROJECT_DIR = path.join(__dirname, '..');
const RUNTIME_DIR = path.join(PROJECT_DIR, 'resources', 'runtime');
const CACHE_DIR = path.join(PROJECT_DIR, 'resources', '.cache');
const DEFAULT_REPO = path.join(PROJECT_DIR, '..', 'open-notebook');

const SURREAL_VERSION = '2.6.5';
const NODE_VERSION = '22.23.2';

// SHA-256 checksums for downloaded binaries. Update these when bumping versions.
const CHECKSUMS = {
  surreal: 'DD9B6FA15EDACBDE96D490DD5727B49B5CF40DF80F29074C7DC17ACB974F509F',
  node: '1177B4137BA5ADAA56354AE40F1080C7450E8AE09CECB47DA459D1C52AC99F97',
};

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function run(cmd, args, opts = {}) {
  // npm is a .cmd shim on Windows and needs a shell; everything else (uv,
  // python, tar, node) is a real exe and must NOT go through a shell, or
  // arguments like `-r <path>` get mangled.
  const shell = opts.shell === true || cmd === 'npm';
  const res = spawnSync(cmd, args, {
    stdio: 'inherit',
    shell,
    ...opts,
  });
  if (res.status !== 0) {
    throw new Error(`Command failed (${res.status}): ${cmd} ${args.join(' ')}`);
  }
  return res;
}

function readFlag(args, name, def) {
  const eq = args.find((a) => a.startsWith(`${name}=`));
  if (eq) return eq.split('=').slice(1).join('=');
  const i = args.indexOf(name);
  if (i !== -1 && args[i + 1]) return args[i + 1];
  return def;
}

function runCapture(cmd, args, opts = {}) {
  const res = spawnSync(cmd, args, {
    encoding: 'utf8',
    ...opts,
  });
  if (res.status !== 0) {
    throw new Error(`Command failed (${res.status}): ${cmd} ${args.join(' ')}`);
  }
  return (res.stdout || '').trim();
}

function log(step, msg) {
  console.log(`\n=== [${step}] ${msg} ===\n`);
}

function sha256File(filePath) {
  return new Promise((resolve, reject) => {
    const hash = crypto.createHash('sha256');
    const stream = fs.createReadStream(filePath);
    stream.on('error', reject);
    stream.on('data', (chunk) => hash.update(chunk));
    stream.on('end', () => resolve(hash.digest('hex').toUpperCase()));
  });
}

function download(url, dest, expectedSha256) {
  fs.mkdirSync(path.dirname(dest), { recursive: true });

  fs.mkdirSync(path.dirname(dest), { recursive: true });
  const tmp = `${dest}.tmp`;
  return new Promise((resolve, reject) => {
    const lib = url.startsWith('https:') ? https : http;
    const request = lib.get(url, { timeout: 300000 }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        res.resume();
        download(res.headers.location, dest, expectedSha256).then(resolve, reject);
        return;
      }
      if (res.statusCode !== 200) {
        res.resume();
        reject(new Error(`Download failed (${res.statusCode}): ${url}`));
        return;
      }
      const file = fs.createWriteStream(tmp);
      res.pipe(file);
      file.on('finish', () => file.close(() => resolve()));
      file.on('error', reject);
    });
    request.on('error', reject);
    request.on('timeout', () => {
      request.destroy();
      reject(new Error(`Download timed out: ${url}`));
    });
  }).then(async () => {
    if (expectedSha256) {
      const actual = await sha256File(tmp);
      if (actual !== expectedSha256.toUpperCase()) {
        fs.unlinkSync(tmp);
        throw new Error(`Checksum mismatch for ${path.basename(dest)}: expected ${expectedSha256}, got ${actual}`);
      }
    }
    fs.renameSync(tmp, dest);
  });
}

function rmrf(p) {
  if (fs.existsSync(p)) fs.rmSync(p, { recursive: true, force: true });
}

function findFile(dir, name) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isFile() && entry.name === name) return full;
    if (entry.isDirectory()) {
      const found = findFile(full, name);
      if (found) return found;
    }
  }
  return null;
}

function cp(src, dest, opts = {}) {
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  // dereference: true follows symlinks (uv-managed Pythons are symlinked),
  // which avoids EPERM on Windows when trying to recreate a symlink.
  fs.cpSync(src, dest, { recursive: true, dereference: true, ...opts });
}

// ---------------------------------------------------------------------------
// Steps
// ---------------------------------------------------------------------------

function buildFrontend(repo) {
  const src = path.join(repo, 'frontend');
  const buildDir = path.join(CACHE_DIR, 'frontend-build');

  // Copy the frontend source into a temp build directory so we don't mutate
  // the upstream clone (especially package-lock.json).
  log('frontend', 'Copying frontend source to temp build directory');
  rmrf(buildDir);
  cp(src, buildDir, {
    filter: (s) => {
      const base = path.basename(s);
      return base !== 'node_modules' && base !== '.next';
    },
  });

  // The upstream lockfile pins ~108 tarball URLs to the npmmirror.com CDN
  // (a mirror of registry.npmjs.org). Newer npm refuses to fetch packages of
  // type "remote" from hosts other than the configured registry, so normalize
  // those URLs back to registry.npmjs.org before installing.
  const lockFile = path.join(buildDir, 'package-lock.json');
  const lock = fs.readFileSync(lockFile, 'utf8');
  if (lock.includes('registry.npmmirror.com')) {
    log('frontend', 'Normalizing npmmirror.com URLs in package-lock.json');
    fs.writeFileSync(lockFile, lock.split('https://registry.npmmirror.com/').join('https://registry.npmjs.org/'), 'utf8');
  }

  log('frontend', 'Installing frontend dependencies (npm ci)');
  run('npm', ['ci'], { cwd: buildDir, timeout: 1200000 });

  log('frontend', 'Building Next.js standalone output');
  run('npm', ['run', 'build'], {
    cwd: buildDir,
    env: { ...process.env, INTERNAL_API_URL: 'http://127.0.0.1:5055' },
    timeout: 1200000,
  });

'use strict';

/**
 * build-installer.js — builds a Windows NSIS installer for the packaged app.
 *
 * Why not electron-builder? On non-admin Windows, electron-builder fails to
 * extract its code-signing cache because 7-Zip cannot create the macOS
 * symlinks without admin/Developer Mode. This script uses the NSIS toolchain
 * directly instead.
 *
 * It copies the packaged app to a short root to stay under the Windows
 * MAX_PATH (260-char) limit, then runs makensis.
 *
 * Usage:
 *   node scripts/build-installer.js [--makensis <path>]
 */

const { spawnSync } = require('child_process');
const fs = require('fs');
const path = require('path');
const os = require('os');

const PROJECT_DIR = path.join(__dirname, '..');
const APP_DIR = path.join(PROJECT_DIR, 'out', 'Office of Equity Open Notebook');
const DIST_DIR = path.join(PROJECT_DIR, 'dist');
const VERSION = '1.14.0';
const PRODUCT_NAME = 'Office of Equity Open Notebook';
const INSTALLER_NAME = `${PRODUCT_NAME}-${VERSION}-Setup.exe`;

function arg(name, def) {
  const i = process.argv.indexOf(name);
  if (i !== -1 && process.argv[i + 1]) return process.argv[i + 1];
  return def;
}

function run(cmd, args, opts = {}) {
  const res = spawnSync(cmd, args, { stdio: 'inherit', ...opts });
  if (res.status !== 0) {
    throw new Error(`Command failed (${res.status}): ${cmd} ${args.join(' ')}`);
  }
  return res;
}

/**
 * robocopy uses exit codes 0–7 for success (with various informational flags).
 * Only 8 and above are actual errors.
 */
function runRobocopy(args) {
  const res = spawnSync('robocopy', args, { stdio: 'inherit' });
  const status = res.status == null ? 999 : res.status;
  if (status > 7) {
    throw new Error(`robocopy failed with exit code ${status}`);
  }
}

function main() {
  if (!fs.existsSync(path.join(APP_DIR, `${PRODUCT_NAME}.exe`))) {
    console.error(`Packaged app not found at ${APP_DIR}. Run \`npm run package:app\` first.`);
    process.exit(1);
  }

  const makensis =
    arg('--makensis', null) ||
    path.join(PROJECT_DIR, 'resources', '.cache', 'nsis', 'nsis-3.09', 'makensis.exe');
  if (!fs.existsSync(makensis)) {
    console.error(`makensis not found at ${makensis}. Download the NSIS 3.x zip to resources/.cache/nsis/.`);
    process.exit(1);
  }

  // Use a unique short-root staging directory per run. This avoids MAX_PATH
  // and guarantees we never clobber user data in a fixed path like C:\onb.
  const shortRoot = path.join('C:\\onb', `build-${process.pid}-${Date.now()}`);
  const shortAppRequired = path.join(shortRoot, 'OpenNotebook-required');
  const shortAppPython = path.join(shortRoot, 'OpenNotebook-python');
  const shortAppNode = path.join(shortRoot, 'OpenNotebook-node');
  const scriptPath = path.join(shortRoot, 'installer.nsi');

  try {
    // Stage three component directories:
    //  - required: everything except the bundled Python and Node runtimes
    //  - python:   resources/runtime/python
    //  - node:     resources/runtime/node
    // Using robocopy /XD avoids fragile cross-directory moves on Windows.
    console.log(`Staging installer components in ${shortRoot}...`);
    fs.mkdirSync(shortRoot, { recursive: true });

    runRobocopy([APP_DIR, shortAppRequired, '/E', '/MT:16', '/XD', 'python', 'node', '/NFL', '/NDL', '/NJH', '/NJS']);
    runRobocopy([path.join(APP_DIR, 'resources', 'runtime', 'python'), path.join(shortAppPython, 'python'), '/E', '/MT:16', '/NFL', '/NDL', '/NJH', '/NJS']);
    runRobocopy([path.join(APP_DIR, 'resources', 'runtime', 'node'), path.join(shortAppNode, 'node'), '/E', '/MT:16', '/NFL', '/NDL', '/NJH', '/NJS']);

    // Write the NSIS script with optional components for Python and Node.
    const installerPath = path.join(DIST_DIR, INSTALLER_NAME);
    fs.mkdirSync(DIST_DIR, { recursive: true });
    const nsisInstallerPath = installerPath.replace(/\\/g, '\\\\').replace(/"/g, '$\\"');
    const script = `
!include "MUI2.nsh"
Name "${PRODUCT_NAME}"
OutFile "${nsisInstallerPath}"
InstallDir "$PROGRAMFILES64\\${PRODUCT_NAME}"
InstallDirRegKey HKLM "Software\\${PRODUCT_NAME}" "InstallDir"
RequestExecutionLevel admin
Unicode true
!define MUI_ABORTWARNING
!insertmacro MUI_PAGE_WELCOME
!insertmacro MUI_PAGE_COMPONENTS
!insertmacro MUI_PAGE_DIRECTORY
!insertmacro MUI_PAGE_INSTFILES
!insertmacro MUI_PAGE_FINISH
!insertmacro MUI_UNPAGE_CONFIRM
!insertmacro MUI_UNPAGE_INSTFILES
!insertmacro MUI_LANGUAGE "English"

Section "Office of Equity Open Notebook (required)" SecApp
  SetOutPath "$INSTDIR"
  File /r "OpenNotebook-required\\*"
  WriteUninstaller "$INSTDIR\\Uninstall.exe"
  WriteRegStr HKLM "Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\${PRODUCT_NAME}" "DisplayName" "${PRODUCT_NAME}"
  WriteRegStr HKLM "Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\${PRODUCT_NAME}" "DisplayVersion" "${VERSION}"
  WriteRegStr HKLM "Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\${PRODUCT_NAME}" "Publisher" "${PRODUCT_NAME} Desktop"
  WriteRegStr HKLM "Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\${PRODUCT_NAME}" "UninstallString" '"$INSTDIR\\Uninstall.exe"'
  WriteRegStr HKLM "Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\${PRODUCT_NAME}" "InstallLocation" "$INSTDIR"
  WriteRegDWORD HKLM "Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\${PRODUCT_NAME}" "NoModify" 1
  WriteRegDWORD HKLM "Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\${PRODUCT_NAME}" "NoRepair" 1
  CreateDirectory "$SMPROGRAMS\\${PRODUCT_NAME}"
  CreateShortcut "$SMPROGRAMS\\${PRODUCT_NAME}\\${PRODUCT_NAME}.lnk" "$INSTDIR\\${PRODUCT_NAME}.exe"
  CreateShortcut "$DESKTOP\\${PRODUCT_NAME}.lnk" "$INSTDIR\\${PRODUCT_NAME}.exe"
SectionEnd

Section "Python 3.12 runtime" SecPython
  SetOutPath "$INSTDIR\\resources\\runtime"
  File /r "OpenNotebook-python\\*"
SectionEnd

Section "Node.js runtime" SecNode
  SetOutPath "$INSTDIR\\resources\\runtime"
  File /r "OpenNotebook-node\\*"
SectionEnd

Section "Uninstall"
  Delete "$INSTDIR\\Uninstall.exe"
  RMDir /r "$INSTDIR"
  Delete "$SMPROGRAMS\\${PRODUCT_NAME}\\${PRODUCT_NAME}.lnk"
  RMDir "$SMPROGRAMS\\${PRODUCT_NAME}"
  Delete "$DESKTOP\\${PRODUCT_NAME}.lnk"
  DeleteRegKey HKLM "Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\${PRODUCT_NAME}"
  DeleteRegKey HKLM "Software\\${PRODUCT_NAME}"
SectionEnd
`;

    fs.writeFileSync(scriptPath, script, 'utf8');

    console.log('Building installer with NSIS (this compresses ~800 MB, please wait)...');
    run(makensis, [scriptPath], { cwd: shortRoot, timeout: 2400000 });

    console.log(`\n✅ Installer created: ${installerPath}`);
  } finally {
    // Always clean up the staging directory, even on failure.
    try {
      fs.rmSync(shortRoot, { recursive: true, force: true });
    } catch (err) {
      console.warn(`Could not remove staging directory ${shortRoot}: ${err.message}`);
    }
  }
}

main();

const { spawnSync } = require('child_process');
const fs = require('fs');
const path = require('path');
const os = require('os');

const PROJECT_DIR = path.join(__dirname, '..', '..');
const RUNTIME_SCRIPT = path.join(PROJECT_DIR, 'scripts', 'prepare-runtime.js');
const LOCK_FILE = path.join(PROJECT_DIR, 'upstream.lock.json');

// We need a dummy repo to run prepare-runtime.js
const DUMMY_REPO = path.join(os.tmpdir(), 'dummy-open-notebook');

function setupDummyRepo() {
  if (fs.existsSync(DUMMY_REPO)) fs.rmSync(DUMMY_REPO, { recursive: true, force: true });
  fs.mkdirSync(DUMMY_REPO, { recursive: true });

  // pyproject.toml is required by prepare-runtime.js
  fs.writeFileSync(path.join(DUMMY_REPO, 'pyproject.toml'), '[project]\ndependencies = []');

  // create dummy git repo
  spawnSync('git', ['init'], { cwd: DUMMY_REPO });
  spawnSync('git', ['config', 'user.email', 'test@example.com'], { cwd: DUMMY_REPO });
  spawnSync('git', ['config', 'user.name', 'Test User'], { cwd: DUMMY_REPO });
  fs.mkdirSync(path.join(DUMMY_REPO, 'open_notebook'));
  fs.writeFileSync(path.join(DUMMY_REPO, 'open_notebook', 'config.py'), 'DATA_FOLDER = "./data"');
  spawnSync('git', ['add', '.'], { cwd: DUMMY_REPO });
  spawnSync('git', ['commit', '-m', 'initial commit'], { cwd: DUMMY_REPO });

  const res = spawnSync('git', ['rev-parse', 'HEAD'], { cwd: DUMMY_REPO, encoding: 'utf8' });
  return res.stdout.trim();
}

const dummyCommit = setupDummyRepo();

let originalLockData = null;
if (fs.existsSync(LOCK_FILE)) {
  originalLockData = fs.readFileSync(LOCK_FILE, 'utf8');
}

function restoreLock() {
  if (originalLockData) {
    fs.writeFileSync(LOCK_FILE, originalLockData, 'utf8');
  } else {
    if (fs.existsSync(LOCK_FILE)) fs.rmSync(LOCK_FILE);
  }
}

try {
  console.log('Test 1: Fail closed on mismatch');
  fs.writeFileSync(LOCK_FILE, JSON.stringify({ commit: 'mismatched-sha' }));
  const res1 = spawnSync(process.execPath, [RUNTIME_SCRIPT, '--repo', DUMMY_REPO, '--step', 'backend'], { encoding: 'utf8' });
  const err1 = res1.stderr || '';
  if (res1.status === 0 || !err1.includes('Upstream commit mismatch')) {
    throw new Error('Expected prepare-runtime.js to fail on mismatch, but it did not. Output:\n' + err1 + (res1.stdout || ''));
  }
  console.log('  -> Passed');

  console.log('Test 2: Success with --override-upstream-check');
  const res2 = spawnSync(process.execPath, [RUNTIME_SCRIPT, '--repo', DUMMY_REPO, '--step', 'backend', '--override-upstream-check'], { encoding: 'utf8' });
  const err2 = res2.stderr || '';
  if (res2.status !== 0 || !err2.includes('Upstream commit mismatch overridden')) {
    throw new Error('Expected prepare-runtime.js to succeed with override, but it failed. Output:\n' + err2 + '\n' + (res2.stdout || ''));
  }
  console.log('  -> Passed');

  console.log('Test 3: Success on match');
  fs.writeFileSync(LOCK_FILE, JSON.stringify({ commit: dummyCommit }));
  const res3 = spawnSync(process.execPath, [RUNTIME_SCRIPT, '--repo', DUMMY_REPO, '--step', 'backend'], { encoding: 'utf8' });
  const out3 = res3.stdout || '';
  if (res3.status !== 0 || !out3.includes('Verified upstream commit')) {
    throw new Error('Expected prepare-runtime.js to succeed on match, but it failed. Output:\n' + (res3.stderr || '') + '\n' + out3);
  }
  console.log('  -> Passed');

  console.log('Test 4: Manifest generated successfully');
  const manifestPath = path.join(PROJECT_DIR, 'resources', 'runtime', 'manifest.json');
  if (!fs.existsSync(manifestPath)) {
    throw new Error('Manifest file was not generated.');
  }
  const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
  if (manifest.upstreamCommit !== dummyCommit) {
    throw new Error(`Manifest has wrong upstreamCommit: expected ${dummyCommit}, got ${manifest.upstreamCommit}`);
  }
  console.log('  -> Passed');

} finally {
  restoreLock();
  if (fs.existsSync(DUMMY_REPO)) fs.rmSync(DUMMY_REPO, { recursive: true, force: true });
}

console.log('All tests passed.');
